(function($){
    'use strict';

    function setBusy($btn, busy, label) {
        if (!$btn || !$btn.length) return;
        if (busy) {
            $btn.addClass('is-busy').prop('disabled', true);
            if (label) $btn.data('orig-label', $btn.text()).text(label);
        } else {
            $btn.removeClass('is-busy').prop('disabled', false);
            if ($btn.data('orig-label')) {
                $btn.text($btn.data('orig-label'));
                $btn.removeData('orig-label');
            }
        }
    }

    // Reload REST log table without reloading the page
    function reloadRestLogTable() {
        var $table = $('table.wp-list-table');
        if (!$table.length) return;
        
        var $form = $('#messages-filter');
        var paged = $form.find('input[name="paged"]').val() || 1;
        var per_page = $form.find('input[name="per_page"]').val() || 20;
        var orderby = $form.find('input[name="orderby"]').val() || 'created_at';
        var order = $form.find('input[name="order"]').val() || 'DESC';
        
        $.post(ContactINRestLog.ajax_url, {
            action: 'contactin_get_rest_logs',
            nonce: ContactINRestLog.nonce,
            paged: paged,
            per_page: per_page,
            orderby: orderby,
            order: order
        }, function(response) {
            if (response && response.success && response.data && response.data.html) {
                $('.wp-list-table-container').html(response.data.html);
            }
        });
    }

    const ACTIONS = {
        VIEW:  'contactin_view_rest_log',
        ADJ:   'contactin_get_adjacent_rest_log',
        PRUNE: 'contactin_prune_rest',
        CLEAR: 'contactin_clear_rest_logs',
        CSV:   'contactin_download_rest_csv'
    };

    // --- Helpers -------------------------------------------------------------

    function renderMeta(d) {
        let html = '';
        html += `<p><strong>Timestamp:</strong> ${d.timestamp || ''}</p>`;
        html += `<p><strong>IP:</strong> ${d.ip_address || ''}</p>`;
        html += `<p><strong>User Agent:</strong> ${d.user_agent || ''}</p>`;
        html += `<p><strong>HTTP Method:</strong> ${d.method || ''}</p>`;
        html += `<p><strong>Endpoint:</strong> ${d.endpoint || ''}</p>`;
        html += `<p><strong>HTTP Code:</strong> ${d.code || ''}</p>`;
        html += `<p><strong>Validated:</strong> ${d.validated ? '✔' : '✖'}</p>`;
        html += `<p><strong>Token valid:</strong> ${d.token_valid ? '✔' : '✖'}</p>`;
        if (d.error_message) {
            html += `<p><strong>Error:</strong> ${d.error_message}</p>`;
        }
        return html;
    }

    function escapeHtml(str) {
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');
    }

    function populateModal(d) {
        $('#contactin-rest-meta').data('log-id', d.id).html(renderMeta(d));
        $('#contactin-rest-headers').html(`<h4>Request Headers</h4><pre>${escapeHtml(d.request_headers || '')}</pre>`);
        $('#contactin-rest-request').html(`<h4>Request Payload</h4><pre>${escapeHtml(d.request_payload || '')}</pre>`);
        $('#contactin-rest-response').html(`<h4>Response Body</h4><pre>${escapeHtml(d.response_body || '')}</pre>`);
    }

    function setDisabled($el, disabled) {
        if ($el.is('button, input')) {
            $el.prop('disabled', disabled);
        } else {
            $el.toggleClass('is-disabled', disabled)
               .attr('aria-disabled', disabled ? 'true' : 'false');
        }
    }

    function updateNavButtons(hasPrev, hasNext) {
        setDisabled($('#contactin-prev-log'), !hasPrev);
        setDisabled($('#contactin-next-log'), !hasNext);
    }

    // Block clicks if disabled
    $(document).on('click', '#contactin-prev-log, #contactin-next-log', function(e) {
        const $el = $(this);
        const isNativeDisabled = $el.is('button, input') && $el.prop('disabled');
        const isAriaDisabled   = $el.attr('aria-disabled') === 'true';
        if (isNativeDisabled || isAriaDisabled || $el.hasClass('is-disabled')) {
            e.preventDefault();
            e.stopImmediatePropagation();
            return false;
        }
    });

    function assertEnv() {
        if (typeof ContactINRestLog !== 'object') {
            console.error('[ContactIN] Missing ContactINRestLog localization.');
            cinShowMessage('Environment error: localization missing.', 'error');
            return false;
        }
        if (!ContactINRestLog.nonce) {
            console.error('[ContactIN] Missing nonce in ContactINRestLog.');
            cinShowMessage('Security error: nonce missing.', 'error');
            return false;
        }
        return true;
    }

    function payload(base) {
        return Object.assign({}, base, { nonce: ContactINRestLog.nonce });
    }

    // --- Event bindings ------------------------------------------------------

    // View details
    $(document).on('click', '.contactin-view-log', function(e){
        e.preventDefault();
        if (!assertEnv()) return;

        const id = $(this).data('id');
        if (!id) {
            cinShowMessage('Invalid log ID.', 'error');
            return;
        }

        // Get current filter values from form
        const http_method = $('#method-filter').val() || 'all';
        const endpoint = $('#endpoint-filter').val() || 'all';
        const http_code = $('#http-code-filter').val() || 'all';
        const validated = $('#validated-filter').val() || 'all';

        $('#contactin-rest-meta').empty();
        $('#contactin-rest-headers').html('<h4>Request Headers</h4><pre>Loading…</pre>');
        $('#contactin-rest-request').html('<h4>Request Payload</h4><pre>Loading…</pre>');
        $('#contactin-rest-response').html('<h4>Response Body</h4><pre>Loading…</pre>');

        cinAjax(ACTIONS.VIEW, payload({ id, http_method, endpoint, http_code, validated }), undefined, undefined, ContactINRestLog)
            .then(res => {
                if (res && res.success) {
                    populateModal(res.data);
                    $('#contactin-rest-modal').addClass('is-active');
                    $('body').addClass('cin-modal-open');
                    updateNavButtons(!!res.data.hasPrev, !!res.data.hasNext);
                } else {
                    $('#contactin-rest-meta').html(res?.data?.message || ContactINRestLog.i18n?.errorDetails || 'Failed to load log details.');
                    updateNavButtons(!!res.data?.hasPrev, !!res.data?.hasNext);
                }
            })
            .catch(err => {
                console.error('[ContactIN] Network/view error:', err);
                $('#contactin-rest-meta').html(ContactINRestLog.i18n?.network_error || 'Network error.');
                updateNavButtons(false, false); // disable both on network error
            });

    });

    // Close modal when clicking backdrop
    $(document).on('click', '.contactin-modal-backdrop', function(){
        $(this).closest('.contactin-modal').removeClass('is-active');
        $('body').removeClass('cin-modal-open');
    });

    // Navigation
    function navigateAdjacentRest(direction){
        if (!assertEnv()) return;
        const currentId = $('#contactin-rest-meta').data('log-id');
        if (!currentId) return;

        // Get current filter values from form
        const http_method = $('#method-filter').val() || 'all';
        const endpoint = $('#endpoint-filter').val() || 'all';
        const http_code = $('#http-code-filter').val() || 'all';
        const validated = $('#validated-filter').val() || 'all';

        const $clicked = direction === 'prev' ? $('#contactin-prev-log') : $('#contactin-next-log');
        setDisabled($clicked, true);

        cinAjax(ACTIONS.ADJ, payload({ direction, current_id: currentId, http_method, endpoint, http_code, validated }), undefined, undefined, ContactINRestLog)
            .then(res => {
                if (res.success) {
                    populateModal(res.data);
                } else {
                    cinShowMessage(res.data?.message || ContactINRestLog.i18n?.errorDetails || 'No more logs in this direction.', 'error');
                }
                updateNavButtons(!!res.data?.hasPrev, !!res.data?.hasNext);
            })
            .catch(err => {
                console.error('[ContactIN] Network/adjacent error:', err);
                cinShowMessage(ContactINRestLog.i18n?.network_error || 'Network error.', 'error');
                setDisabled($clicked, false); // re‑enable on error
            });
    }

    $('#contactin-prev-log').on('click', () => navigateAdjacentRest('prev'));
    $('#contactin-next-log').on('click', () => navigateAdjacentRest('next'));

    // Prune
    $('#contactin-prune-btn, #contactin-prune-logs').on('click', function(e){
        e.preventDefault();
        if (!assertEnv()) return;

        const days = ContactINRestLog.retention_days || 30;
        const msg = ContactINRestLog.i18n?.confirmPrune
            || `This will permanently delete all REST API logs older than ${days} days. Proceed?`;
        if (!confirm(msg)) return;

        cinAjax(ACTIONS.PRUNE, payload({}), undefined, undefined, ContactINRestLog)
            .then(res => {
                cinShowMessage(res.data?.message || ContactINRestLog.i18n?.pruning || 'Pruning…', res.success ? 'success' : 'error');
            })
            .catch(err => {
                console.error('[ContactIN] Network/prune error:', err);
                cinShowMessage(ContactINRestLog.i18n?.errorPrune || 'Error pruning logs.', 'error');
            });
    });
    // Prune Old Logs
    $('#contactin-prune-rest-btn').on('click', function(e){
        e.preventDefault();
        if (!assertEnv()) return;

        if (!confirm(ContactINRestLog.i18n?.confirmPrune || 'This will delete REST logs older than 30 days. Continue?')) return;

        const $btn = $(this);
        setBusy($btn, true, ContactINRestLog.i18n?.working || 'Working...');

        $.post(ContactINRestLog.ajax_url, payload({ action: ACTIONS.PRUNE }))
            .done(res => {
                if (res.success) {
                    cinShowMessage(res.data.message || 'Logs pruned successfully.', 'success');
                    setBusy($btn, false);
                    setTimeout(() => reloadRestLogTable(), 1500);
                } else {
                    cinShowMessage(res.data?.message || 'Failed to prune logs.', 'error');
                    setBusy($btn, false);
                }
            })
            .fail(err => {
                console.error('[ContactIN] Network/prune error:', err);
                cinShowMessage(ContactINRestLog.i18n?.network_error || 'Network error.', 'error');
                setBusy($btn, false);
            });
    });

    // Clear All Logs
    $('#contactin-clear-rest-logs').on('click', function(e){
        e.preventDefault();
        if (!assertEnv()) return;

        if (!confirm(ContactINRestLog.i18n?.confirmClear || 'This will permanently delete ALL REST API logs. This action cannot be undone. Continue?')) return;

        const $btn = $(this);
        setBusy($btn, true, ContactINRestLog.i18n?.working || 'Working...');

        $.post(ContactINRestLog.ajax_url, payload({ action: ACTIONS.CLEAR }))
            .done(res => {
                if (res.success) {
                    cinShowMessage(res.data.message || 'All logs cleared successfully.', 'success');
                    setBusy($btn, false);
                    setTimeout(() => reloadRestLogTable(), 1500);
                } else {
                    cinShowMessage(res.data?.message || 'Failed to clear logs.', 'error');
                    setBusy($btn, false);
                }
            })
            .fail(err => {
                console.error('[ContactIN] Network/clear error:', err);
                cinShowMessage(ContactINRestLog.i18n?.network_error || 'Network error.', 'error');
                setBusy($btn, false);
            });
    });
    // Download CSV
    $('#contactin-download-rest-csv').on('click', function(e){
        e.preventDefault();
        if (!assertEnv()) return;

        const $btn = $(this);
        const baseUrl = ContactINRestLog.ajax_url + '?action=contactinbox_download_rest_csv&nonce=' + encodeURIComponent(ContactINRestLog.nonce);
        
        const filters = {
            method:    $('#method-filter').val(),
            endpoint:  $('#endpoint-filter').val(),
            http_code: $('#http-filter').val(),
            validated: $('#validated-filter').val(),
        };

        if (typeof window.cinExportHelper === 'function') {
            const fullUrl = baseUrl + '&method=' + encodeURIComponent(filters.method || 'all') +
                           '&endpoint=' + encodeURIComponent(filters.endpoint || 'all') +
                           '&http_code=' + encodeURIComponent(filters.http_code || 'all') +
                           '&validated=' + encodeURIComponent(filters.validated || 'all');
            
            window.cinExportHelper({
                infoAction: 'contactinbox_rest_export_info',
                baseUrl: fullUrl
            });
        } else {
            // Fallback: direct download
            window.location.href = baseUrl;
        }
    });

    // Utility: use global message box for consistent styling
    function cinShowMessage(msg, type) {
        if (typeof window.cinShowMessage === 'function') {
            window.cinShowMessage(msg, type === 'error' ? 'error' : 'success');
            return;
        }
        // Fallback to inline notice if global helper missing
        var $box = $('#contactin-rest-notice');
        $box.removeClass('notice-success notice-error').addClass(type === 'error' ? 'notice-error' : 'notice-success');
        $box.text(msg);
        $box.stop(true, true).fadeIn(150).delay(3500).fadeOut(600);
    }

})(jQuery);
